code:
import { workflow, node, trigger, ifElse, expr, newCredential } from '@n8n/workflow-sdk';

const PG_CRED = newCredential('Postgres account');
const OAI_CRED = newCredential('OpenAI account');

const trig = trigger({
  type: 'n8n-nodes-base.executeWorkflowTrigger',
  version: 1.2,
  config: {
    name: 'Trigger',
    parameters: {
      inputSource: 'workflowInputs',
      workflowInputs: {
        values: [
          { name: 'chunkIds', type: 'array' },
          { name: 'requestId', type: 'string' },
          { name: 'userId', type: 'string' },
          { name: 'sessionId', type: 'string' },
        ],
      },
    },
    output: [
      {
        json: {
          chunkIds: ['11111111-1111-1111-1111-111111111111'],
          requestId: '22222222-2222-2222-2222-222222222222',
          userId: '',
          sessionId: '',
        },
      },
    ],
  },
});

const normalizar = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Normalizar entrada',
    parameters: {
      mode: 'runOnceForAllItems',
      language: 'javaScript',
      jsCode: `const item = $input.first().json || {};
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
let ids = item.chunkIds;
if (typeof ids === 'string') {
  try { ids = JSON.parse(ids); } catch (_) { ids = ids.split(/[\\s,]+/); }
}
if (!Array.isArray(ids)) ids = [];
const chunkIds = [...new Set(ids.map((x) => String(x || '').trim()).filter((x) => UUID_RE.test(x)))];
const requestId = String(item.requestId || '').trim();
const userId = String(item.userId || '').trim();
const sessionId = String(item.sessionId || '').trim();
const startedAtMs = Date.now();
if (!chunkIds.length) {
  return [{ json: { ok: true, empty: true, requestId, userId, sessionId, startedAtMs, total: 0, skippedValid: 0, skippedEmpty: 0, generated: 0, failed: 0, pending: 0 } }];
}
const idList = chunkIds.map((id) => "'" + id.replace(/'/g, "''") + "'::uuid").join(',');
const loadSql =
  "SELECT id, document_id AS \\"documentId\\", document_version_id AS \\"versionId\\", " +
  "COALESCE(chunk_text, '') AS \\"chunkText\\", content_hash AS \\"contentHash\\", " +
  "embedding_status AS \\"embeddingStatus\\", embedding_hash AS \\"embeddingHash\\", " +
  "embedding_attempts AS \\"embeddingAttempts\\", " +
  "(embedding_vector IS NOT NULL) AS \\"hasVector\\" " +
  "FROM document_chunks WHERE id IN (" + idList + ")";
return [{ json: { ok: true, empty: false, chunkIds, idList, loadSql, requestId, userId, sessionId, startedAtMs } }];`,
    },
  },
  output: [
    {
      json: {
        ok: true,
        empty: false,
        chunkIds: ['11111111-1111-1111-1111-111111111111'],
        idList: "'11111111-1111-1111-1111-111111111111'::uuid",
        loadSql: 'SELECT 1',
        requestId: '22222222-2222-2222-2222-222222222222',
        userId: '',
        sessionId: '',
        startedAtMs: 0,
      },
    },
  ],
});

const earlyEmpty = ifElse({
  version: 2.3,
  config: {
    name: 'Entrada vazia?',
    parameters: {
      conditions: {
        combinator: 'and',
        options: { caseSensitive: true, leftValue: '', typeValidation: 'loose', version: 2 },
        conditions: [
          {
            id: 'e1',
            leftValue: expr('={{ $json.empty === true }}'),
            rightValue: true,
            operator: { type: 'boolean', operation: 'true' },
          },
        ],
      },
      looseTypeValidation: true,
    },
  },
});

const carregarSecrets = node({
  type: 'n8n-nodes-base.postgres',
  version: 2.6,
  config: {
    name: 'Carregar secrets',
    credentials: { postgres: PG_CRED },
    parameters: {
      operation: 'executeQuery',
      options: {},
      query:
        "SELECT\n" +
        "  MAX(CASE WHEN key = 'embedding_model' THEN value END) AS model,\n" +
        "  MAX(CASE WHEN key = 'embedding_dimensions' THEN value END) AS dimensions,\n" +
        "  MAX(CASE WHEN key = 'embedding_max_retries' THEN value END) AS max_retries,\n" +
        "  MAX(CASE WHEN key = 'embedding_engine_version' THEN value END) AS engine_version,\n" +
        "  MAX(CASE WHEN key = 'embedding_timeout_ms' THEN value END) AS timeout_ms\n" +
        "FROM app_secrets\n" +
        "WHERE key IN ('embedding_model','embedding_dimensions','embedding_max_retries','embedding_engine_version','embedding_timeout_ms');",
    },
  },
  output: [
    {
      json: {
        model: 'text-embedding-3-small',
        dimensions: '1536',
        max_retries: '3',
        engine_version: '1.0.0',
        timeout_ms: '60000',
      },
    },
  ],
});

const carregarChunks = node({
  type: 'n8n-nodes-base.postgres',
  version: 2.6,
  config: {
    name: 'Carregar chunks',
    credentials: { postgres: PG_CRED },
    alwaysOutputData: true,
    parameters: {
      operation: 'executeQuery',
      options: {},
      query: expr("={{ $('Normalizar entrada').first().json.loadSql }}"),
    },
  },
  output: [
    {
      json: {
        id: '11111111-1111-1111-1111-111111111111',
        documentId: '33333333-3333-3333-3333-333333333333',
        versionId: '44444444-4444-4444-4444-444444444444',
        chunkText: 'texto',
        contentHash: 'abc',
        embeddingStatus: 'PENDING',
        embeddingHash: null,
        embeddingAttempts: 0,
        hasVector: false,
      },
    },
  ],
});

const classificar = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Classificar chunks',
    parameters: {
      mode: 'runOnceForAllItems',
      language: 'javaScript',
      jsCode: `const norm = $('Normalizar entrada').first().json || {};
const secrets = $('Carregar secrets').first().json || {};
const rows = $input.all().map((i) => i.json).filter((j) => j && j.id);
const model = String(secrets.model || 'text-embedding-3-small');
const dimensions = Number(secrets.dimensions || 1536) || 1536;
const maxRetries = Number(secrets.max_retries || 3) || 3;
const engineVersion = Number(String(secrets.engine_version || '1').split('.')[0]) || 1;
const timeoutMs = Number(secrets.timeout_ms || 60000) || 60000;

const skippedValid = [];
const skippedEmpty = [];
const toProcess = [];

for (const row of rows) {
  const text = String(row.chunkText || '').trim();
  const contentHash = String(row.contentHash || '').trim();
  const status = String(row.embeddingStatus || '');
  const embHash = String(row.embeddingHash || '').trim();
  const hasVector = row.hasVector === true || row.hasVector === 't' || row.hasVector === 'true';
  if (!text) {
    skippedEmpty.push(row.id);
    continue;
  }
  if (status === 'VALID' && hasVector && contentHash && embHash && contentHash === embHash) {
    skippedValid.push(row.id);
    continue;
  }
  toProcess.push({ id: row.id, text, contentHash });
}

function esc(s) { return String(s ?? '').replace(/'/g, "''"); }
let markSkippedSql = 'SELECT 0 AS noop WHERE false';
if (skippedEmpty.length) {
  markSkippedSql =
    "UPDATE document_chunks SET embedding_status = 'SKIPPED', embedding_vector = NULL, embedding_hash = NULL, " +
    "embedding_updated_at = now(), embedding_last_error = NULL, embedding_next_retry_at = NULL " +
    "WHERE id IN (" + skippedEmpty.map((id) => "'" + esc(id) + "'::uuid").join(',') + ") RETURNING id";
}

let markProcessingSql = 'SELECT 0 AS noop WHERE false';
if (toProcess.length) {
  markProcessingSql =
    "UPDATE document_chunks SET embedding_status = 'PROCESSING', embedding_updated_at = now(), embedding_last_error = NULL " +
    "WHERE id IN (" + toProcess.map((c) => "'" + esc(c.id) + "'::uuid").join(',') + ") RETURNING id";
}

const openaiBody = { model, input: toProcess.map((c) => c.text), dimensions };
return [{
  json: {
    requestId: norm.requestId,
    userId: norm.userId,
    sessionId: norm.sessionId,
    startedAtMs: norm.startedAtMs,
    model,
    dimensions,
    maxRetries,
    engineVersion,
    timeoutMs,
    total: rows.length,
    skippedValid: skippedValid.length,
    skippedEmpty: skippedEmpty.length,
    toProcessCount: toProcess.length,
    toProcessIds: toProcess.map((c) => c.id),
    toProcessHashes: toProcess.map((c) => c.contentHash),
    markSkippedSql,
    markProcessingSql,
    openaiBody,
    hasWork: toProcess.length > 0,
  },
}];`,
    },
  },
  output: [
    {
      json: {
        requestId: '22222222-2222-2222-2222-222222222222',
        startedAtMs: 0,
        model: 'text-embedding-3-small',
        dimensions: 1536,
        maxRetries: 3,
        engineVersion: 1,
        total: 1,
        skippedValid: 0,
        skippedEmpty: 0,
        toProcessCount: 1,
        toProcessIds: ['11111111-1111-1111-1111-111111111111'],
        toProcessHashes: ['abc'],
        markSkippedSql: 'SELECT 0',
        markProcessingSql: 'SELECT 0',
        openaiBody: { model: 'text-embedding-3-small', input: ['texto'], dimensions: 1536 },
        hasWork: true,
      },
    },
  ],
});

const marcarSkipped = node({
  type: 'n8n-nodes-base.postgres',
  version: 2.6,
  config: {
    name: 'Marcar SKIPPED',
    credentials: { postgres: PG_CRED },
    alwaysOutputData: true,
    parameters: {
      operation: 'executeQuery',
      options: {},
      query: expr('={{ $json.markSkippedSql }}'),
    },
  },
  output: [{ json: { id: null } }],
});

const hasWork = ifElse({
  version: 2.3,
  config: {
    name: 'Tem trabalho?',
    parameters: {
      conditions: {
        combinator: 'and',
        options: { caseSensitive: true, leftValue: '', typeValidation: 'loose', version: 2 },
        conditions: [
          {
            id: 'w1',
            leftValue: expr("={{ $('Classificar chunks').first().json.hasWork === true }}"),
            rightValue: true,
            operator: { type: 'boolean', operation: 'true' },
          },
        ],
      },
      looseTypeValidation: true,
    },
  },
});

const marcarProcessing = node({
  type: 'n8n-nodes-base.postgres',
  version: 2.6,
  config: {
    name: 'Marcar PROCESSING',
    credentials: { postgres: PG_CRED },
    alwaysOutputData: true,
    parameters: {
      operation: 'executeQuery',
      options: {},
      query: expr("={{ $('Classificar chunks').first().json.markProcessingSql }}"),
    },
  },
  output: [{ json: { id: '11111111-1111-1111-1111-111111111111' } }],
});

const chamarOpenAI = node({
  type: 'n8n-nodes-base.httpRequest',
  version: 4.4,
  config: {
    name: 'OpenAI Embeddings',
    credentials: { openAiApi: OAI_CRED },
    onError: 'continueRegularOutput',
    alwaysOutputData: true,
    parameters: {
      method: 'POST',
      url: 'https://api.openai.com/v1/embeddings',
      authentication: 'predefinedCredentialType',
      nodeCredentialType: 'openAiApi',
      sendBody: true,
      contentType: 'json',
      specifyBody: 'json',
      jsonBody: expr("={{ $('Classificar chunks').first().json.openaiBody }}"),
      options: {
        timeout: expr("={{ $('Classificar chunks').first().json.timeoutMs || 60000 }}"),
        response: { response: { fullResponse: true, neverError: true } },
      },
    },
  },
  output: [
    {
      json: {
        statusCode: 200,
        body: {
          data: [{ embedding: [0.1, 0.2], index: 0 }],
          usage: { prompt_tokens: 3, total_tokens: 3 },
        },
      },
    },
  ],
});

const processarResposta = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Processar resposta',
    parameters: {
      mode: 'runOnceForAllItems',
      language: 'javaScript',
      jsCode: `const cls = $('Classificar chunks').first().json || {};
const resp = $input.first().json || {};
const statusCode = Number(resp.statusCode ?? resp.status ?? 0);
let body = resp.body ?? resp.data ?? resp;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (_) { body = {}; }
}
const okHttp = statusCode >= 200 && statusCode < 300;
const data = Array.isArray(body && body.data) ? body.data : [];
const ids = cls.toProcessIds || [];
const hashes = cls.toProcessHashes || [];
const generationMs = Math.max(0, Date.now() - Number(cls.startedAtMs || Date.now()));
const tokenCount = body && body.usage ? Number(body.usage.total_tokens || body.usage.prompt_tokens || 0) : 0;
const dimensions = Number(cls.dimensions || 1536) || 1536;
const model = String(cls.model || 'text-embedding-3-small');
const engineVersion = Number(cls.engineVersion || 1) || 1;
const maxRetries = Number(cls.maxRetries || 3) || 3;

function esc(s) { return String(s ?? '').replace(/'/g, "''"); }

let persistSql = 'SELECT 0 AS noop WHERE false';
let failSql = 'SELECT 0 AS noop WHERE false';
let generated = 0;
let failed = 0;

if (okHttp && data.length) {
  const byIndex = new Map();
  for (const item of data) byIndex.set(Number(item.index), item.embedding);
  const values = [];
  for (let i = 0; i < ids.length; i++) {
    const emb = byIndex.get(i);
    if (!Array.isArray(emb) || !emb.length) {
      failed += 1;
      continue;
    }
    generated += 1;
    const vectorJson = JSON.stringify(emb).replace(/'/g, "''");
    const hash = esc(hashes[i] || '');
    values.push(
      "('" + esc(ids[i]) + "'::uuid, '" + vectorJson + "'::jsonb, '" + hash + "', " +
      "'" + esc(model) + "', " + dimensions + ", " + engineVersion + ", " +
      generationMs + ", " + (tokenCount || 'NULL') + ")"
    );
  }
  if (values.length) {
    persistSql =
      "UPDATE document_chunks AS dc SET\\n" +
      "  embedding_vector = v.vec,\\n" +
      "  embedding_status = 'VALID',\\n" +
      "  embedding_hash = v.content_hash,\\n" +
      "  content_hash = COALESCE(NULLIF(dc.content_hash, ''), v.content_hash),\\n" +
      "  embedding_model = v.model,\\n" +
      "  embedding_dimensions = v.dims,\\n" +
      "  embedding_version = v.eng_ver,\\n" +
      "  embedding_generation_ms = v.gen_ms,\\n" +
      "  embedding_token_count = v.tokens,\\n" +
      "  embedding_created_at = COALESCE(dc.embedding_created_at, now()),\\n" +
      "  embedding_updated_at = now(),\\n" +
      "  embedding_last_error = NULL,\\n" +
      "  embedding_next_retry_at = NULL\\n" +
      "FROM (VALUES " + values.join(',') + ") AS v(id, vec, content_hash, model, dims, eng_ver, gen_ms, tokens)\\n" +
      "WHERE dc.id = v.id\\nRETURNING dc.id";
  }
  const missingIds = ids.filter((_, i) => !byIndex.has(i) || !Array.isArray(byIndex.get(i)) || !byIndex.get(i).length);
  if (missingIds.length) {
    failSql =
      "UPDATE document_chunks SET\\n" +
      "  embedding_attempts = embedding_attempts + 1,\\n" +
      "  embedding_last_error = 'missing_embedding_in_response',\\n" +
      "  embedding_status = CASE WHEN embedding_attempts + 1 >= " + maxRetries + " THEN 'FAILED' ELSE 'PENDING' END,\\n" +
      "  embedding_next_retry_at = now() + ((POWER(2, LEAST(embedding_attempts + 1, 6))::int || ' minutes')::interval),\\n" +
      "  embedding_updated_at = now(),\\n" +
      "  embedding_vector = NULL\\n" +
      "WHERE id IN (" + missingIds.map((id) => "'" + esc(id) + "'::uuid").join(',') + ")\\nRETURNING id, embedding_status";
  }
} else {
  failed = ids.length;
  const errMsg = esc(
    (body && (body.error && (body.error.message || body.error.code))) ||
    resp.error ||
    ('http_' + statusCode) ||
    'openai_embeddings_failed'
  ).slice(0, 500);
  if (ids.length) {
    failSql =
      "UPDATE document_chunks SET\\n" +
      "  embedding_attempts = embedding_attempts + 1,\\n" +
      "  embedding_last_error = '" + errMsg + "',\\n" +
      "  embedding_status = CASE WHEN embedding_attempts + 1 >= " + maxRetries + " THEN 'FAILED' ELSE 'PENDING' END,\\n" +
      "  embedding_next_retry_at = now() + ((POWER(2, LEAST(embedding_attempts + 1, 6))::int || ' minutes')::interval),\\n" +
      "  embedding_updated_at = now(),\\n" +
      "  embedding_vector = NULL\\n" +
      "WHERE id IN (" + ids.map((id) => "'" + esc(id) + "'::uuid").join(',') + ")\\nRETURNING id, embedding_status";
  }
}

return [{
  json: {
    requestId: cls.requestId,
    userId: cls.userId,
    sessionId: cls.sessionId,
    startedAtMs: cls.startedAtMs,
    total: cls.total,
    skippedValid: cls.skippedValid,
    skippedEmpty: cls.skippedEmpty,
    generated,
    failed,
    persistSql,
    failSql,
    okHttp,
    statusCode,
  },
}];`,
    },
  },
  output: [
    {
      json: {
        requestId: '22222222-2222-2222-2222-222222222222',
        total: 1,
        skippedValid: 0,
        skippedEmpty: 0,
        generated: 1,
        failed: 0,
        persistSql: 'SELECT 0',
        failSql: 'SELECT 0',
        okHttp: true,
        statusCode: 200,
      },
    },
  ],
});

const persistValid = node({
  type: 'n8n-nodes-base.postgres',
  version: 2.6,
  config: {
    name: 'Persistir VALID',
    credentials: { postgres: PG_CRED },
    alwaysOutputData: true,
    parameters: {
      operation: 'executeQuery',
      options: {},
      query: expr('={{ $json.persistSql }}'),
    },
  },
  output: [{ json: { id: '11111111-1111-1111-1111-111111111111' } }],
});

const persistFail = node({
  type: 'n8n-nodes-base.postgres',
  version: 2.6,
  config: {
    name: 'Persistir falhas',
    credentials: { postgres: PG_CRED },
    alwaysOutputData: true,
    parameters: {
      operation: 'executeQuery',
      options: {},
      query: expr("={{ $('Processar resposta').first().json.failSql }}"),
    },
  },
  output: [{ json: { id: null } }],
});

const finalizarComTrabalho = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Finalizar com trabalho',
    parameters: {
      mode: 'runOnceForAllItems',
      language: 'javaScript',
      jsCode: `const p = $('Processar resposta').first().json || {};
const pending = Number(p.failed || 0);
const ok = Number(p.generated || 0) > 0 || (Number(p.failed || 0) === 0 && Number(p.toProcessCount || 0) === 0);
return [{
  json: {
    ok: Number(p.failed || 0) === 0,
    requestId: p.requestId || '',
    total: Number(p.total || 0),
    skippedValid: Number(p.skippedValid || 0),
    skippedEmpty: Number(p.skippedEmpty || 0),
    generated: Number(p.generated || 0),
    failed: Number(p.failed || 0),
    pending,
    durationMs: Math.max(0, Date.now() - Number(p.startedAtMs || Date.now())),
    statusCode: p.statusCode || null,
  },
}];`,
    },
  },
  output: [
    {
      json: {
        ok: true,
        requestId: '22222222-2222-2222-2222-222222222222',
        total: 1,
        skippedValid: 0,
        skippedEmpty: 0,
        generated: 1,
        failed: 0,
        pending: 0,
        durationMs: 10,
      },
    },
  ],
});

const finalizarSemTrabalho = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Finalizar sem trabalho',
    parameters: {
      mode: 'runOnceForAllItems',
      language: 'javaScript',
      jsCode: `const cls = $('Classificar chunks').first().json || {};
return [{
  json: {
    ok: true,
    requestId: cls.requestId || '',
    total: Number(cls.total || 0),
    skippedValid: Number(cls.skippedValid || 0),
    skippedEmpty: Number(cls.skippedEmpty || 0),
    generated: 0,
    failed: 0,
    pending: 0,
    durationMs: Math.max(0, Date.now() - Number(cls.startedAtMs || Date.now())),
  },
}];`,
    },
  },
  output: [
    {
      json: {
        ok: true,
        requestId: '22222222-2222-2222-2222-222222222222',
        total: 1,
        skippedValid: 1,
        skippedEmpty: 0,
        generated: 0,
        failed: 0,
        pending: 0,
        durationMs: 1,
      },
    },
  ],
});

const finalizarVazio = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: {
    name: 'Finalizar vazio',
    parameters: {
      mode: 'runOnceForAllItems',
      language: 'javaScript',
      jsCode: `const n = $('Normalizar entrada').first().json || {};
return [{
  json: {
    ok: true,
    requestId: n.requestId || '',
    total: 0,
    skippedValid: 0,
    skippedEmpty: 0,
    generated: 0,
    failed: 0,
    pending: 0,
    durationMs: Math.max(0, Date.now() - Number(n.startedAtMs || Date.now())),
  },
}];`,
    },
  },
  output: [
    {
      json: {
        ok: true,
        requestId: '22222222-2222-2222-2222-222222222222',
        total: 0,
        skippedValid: 0,
        skippedEmpty: 0,
        generated: 0,
        failed: 0,
        pending: 0,
        durationMs: 0,
      },
    },
  ],
});

export default workflow('embedding-gerar', 'EMBEDDING - GERAR')
  .add(trig)
  .to(
    normalizar.to(
      earlyEmpty
        .onTrue(finalizarVazio)
        .onFalse(
          carregarSecrets.to(
            carregarChunks.to(
              classificar.to(
                marcarSkipped.to(
                  hasWork
                    .onTrue(
                      marcarProcessing
                        .to(chamarOpenAI)
                        .to(processarResposta)
                        .to(persistValid)
                        .to(persistFail)
                        .to(finalizarComTrabalho)
                    )
                    .onFalse(finalizarSemTrabalho)
                )
              )
            )
          )
        )
    )
  );
